(()=>{'use strict';const active=new Map();function duration(value){return Array.from(String(value)).reduce((ms,c)=>ms+(/[.!?]/.test(c)?120:/[,;:\n]/.test(c)?65:/\s/.test(c)?12:18),0);}
async function reveal(target,value){const chars=Array.from(String(value||'')),container=target.closest?.('.ask-franklin-messages');target.replaceChildren();const text=document.createTextNode('');target.append(text);const row=target.closest?.('.ask-franklin-message');if(row)row.dataset.typing='true';target.setAttribute('aria-busy','true');let complete=false;const finish=()=>{if(complete)return;complete=true;text.textContent=chars.join('');target.setAttribute('aria-busy','false');if(row)delete row.dataset.typing;active.delete(target);};active.set(target,finish);if(matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return;}let i=0;while(i<chars.length&&!complete){if(!target.isConnected){finish();break;}const nearBottom=container&&container.scrollHeight-container.scrollTop-container.clientHeight<90;let chunk='';let wait=0;for(let n=0;n<3&&i<chars.length;n++){const c=chars[i++];chunk+=c;wait+=/[.!?]/.test(c)?120:/[,;:\n]/.test(c)?65:/\s/.test(c)?12:18;}text.appendData(chunk);if(nearBottom)container.scrollTop=container.scrollHeight;await new Promise(resolve=>setTimeout(resolve,wait));}finish();}
window.FranklinTyping={reveal,duration,finish:()=>active.forEach(f=>f())};document.addEventListener('visibilitychange',()=>{if(document.hidden)window.FranklinTyping.finish();});})();
